#include "compositors/niri/niri_config_keyboard.h"

#include "compositors/niri/niri_config_files.h"

#include <cstdlib>
#include <string_view>
#include <xkbcommon/xkbcommon.h>

namespace compositors::niri {
  namespace {

    constexpr std::string_view kManagedHeader =
        "// Generated by Helix from Settings → Keybinds. Edits here are overwritten.\n";
    constexpr std::string_view kKeymapFileName = "helix-keymap.xkb";

    constexpr std::string_view kXkbRules =
        R"(// Generated by Helix from Settings → Keybinds. Edits here are overwritten.
! include %S/evdev

! option = symbols
  helix:quickinsert = +helix(quickinsert)
)";

    constexpr std::string_view kXkbSymbols =
        R"(// Generated by Helix from Settings → Keybinds. Edits here are overwritten.
partial modifier_keys
xkb_symbols "quickinsert" {
    replace key <CAPS> { [ F19 ], type[group1] = "ONE_LEVEL" };
};
)";

    [[nodiscard]] bool bindUsesQuickInsertCaps(const ParsedBind& bind) {
      if (bind.ipcCommand.find("quick-insert") == std::string::npos) {
        return false;
      }
      return bind.key == "F19" || bind.key == "Caps_Lock";
    }

    [[nodiscard]] bool wantsQuickInsertCaps(const std::vector<ParsedBind>& binds) {
      for (const auto& bind : binds) {
        if (bindUsesQuickInsertCaps(bind)) {
          return true;
        }
      }
      return false;
    }

    [[nodiscard]] std::string quoteKdlPath(const std::filesystem::path& path) {
      std::string out = "\"";
      const std::string text = path.string();
      for (const char c : text) {
        if (c == '\\' || c == '"') {
          out.push_back('\\');
        }
        out.push_back(c);
      }
      out.push_back('"');
      return out;
    }

    [[nodiscard]] std::string keyboardKdl(bool enabled, const std::filesystem::path& keymapPath) {
      std::string body = std::string(kManagedHeader);
      if (!enabled) {
        return body;
      }
      body += "input {\n";
      body += "    keyboard {\n";
      body += "        xkb {\n";
      body += "            file ";
      body += quoteKdlPath(keymapPath);
      body += "\n";
      body += "        }\n";
      body += "    }\n";
      body += "}\n";
      return body;
    }

    bool writeOverlayXkb(const std::filesystem::path& xkbDir, std::string& error) {
      if (!writeFile(xkbDir / "symbols" / "helix", kXkbSymbols, error)) {
        return false;
      }
      return writeFile(xkbDir / "rules" / "evdev", kXkbRules, error);
    }

    bool
    compileKeymap(const std::filesystem::path& xkbDir, const std::filesystem::path& keymapPath, std::string& error) {
      xkb_context* context = xkb_context_new(XKB_CONTEXT_NO_DEFAULT_INCLUDES);
      if (context == nullptr) {
        error = "failed to create xkb context";
        return false;
      }
      if (xkb_context_include_path_append(context, xkbDir.string().c_str()) != 1
          || xkb_context_include_path_append_default(context) != 1) {
        xkb_context_unref(context);
        error = "failed to set xkb include paths";
        return false;
      }
      const xkb_rule_names names{
          .rules = nullptr,
          .model = "pc105",
          .layout = "us",
          .variant = nullptr,
          .options = "helix:quickinsert",
      };
      xkb_keymap* keymap = xkb_keymap_new_from_names(context, &names, XKB_KEYMAP_COMPILE_NO_FLAGS);
      if (keymap == nullptr) {
        xkb_context_unref(context);
        error = "failed to compile Quick Insert keymap";
        return false;
      }
      char* text = xkb_keymap_get_as_string(keymap, XKB_KEYMAP_FORMAT_TEXT_V1);
      xkb_keymap_unref(keymap);
      xkb_context_unref(context);
      if (text == nullptr) {
        error = "failed to serialize Quick Insert keymap";
        return false;
      }
      const bool ok = writeFile(keymapPath, text, error);
      std::free(text);
      return ok;
    }

  } // namespace

  bool syncQuickInsertKeyboard(
      const std::filesystem::path& configFile, const std::vector<ParsedBind>& binds, std::string& error
  ) {
    if (configFile.empty()) {
      error = "niri config path is unknown";
      return false;
    }
    const auto dir = configFile.parent_path();
    const auto keymapPath = dir / std::string(kKeymapFileName);
    const bool enabled = wantsQuickInsertCaps(binds);
    if (enabled) {
      if (!writeOverlayXkb(dir / "xkb", error) || !compileKeymap(dir / "xkb", keymapPath, error)) {
        return false;
      }
    }
    if (!writeFile(dir / std::string(kKeyboardIncludeFileName), keyboardKdl(enabled, keymapPath), error)) {
      return false;
    }
    return appendInclude(configFile, kKeyboardIncludeFileName, error);
  }

} // namespace compositors::niri
